import { useState } from 'react';import { useNavigate } from 'react-router-dom';import { useApp } from '../../contexts/AppContext';
export default function Login(){const [admin,setAdmin]=useState(false);const {setUser}=useApp();const nav=useNavigate();function entrar(){const u={id:'1',nome:admin?'Administrador':'Cliente',email:admin?'admin@graficawcriacoes.com':'cliente@email.com',role:admin?'admin':'user'} as const;localStorage.setItem('gp_token','demo-token');setUser(u);nav(admin?'/admin':'/minha-conta')}return <section className="containerx py-16 fade"><div className="card p-8 max-w-md mx-auto"><h1 className="font-display text-4xl text-primary">Login</h1><div className="flex gap-2 mt-5"><button className={`btn ${!admin?'btn-primary':'btn-dark'} flex-1`} onClick={()=>setAdmin(false)}>Cliente</button><button className={`btn ${admin?'btn-primary':'btn-dark'} flex-1`} onClick={()=>setAdmin(true)}>Admin</button></div><div className="grid gap-4 mt-6"><input className="input" placeholder="Email"/><input className="input" type="password" placeholder="Senha"/><button className="btn btn-primary" onClick={entrar}>Entrar</button><a className="text-sm text-accent font-bold">Esqueci a senha</a></div></div></section>}
